<?php $e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$url=fn($p)=>html_entity_decode($this->uri($p,'systemmanagement'),ENT_QUOTES,'UTF-8');$icons=$this->getObject('iconservice','ui');$hidden='<input type="hidden" name="csrf_token" value="'.$e($systemCsrf).'">'; ?>
<main class="chisimba-workspace chisimba-flow system-management"><header class="chisimba-page-header chisimba-card"><div><p class="chisimba-eyebrow">Site administration</p><h1>System management</h1><p>Plan service interruptions and communicate clearly with the people who use this site.</p></div></header>
<?php if($systemMessage):?><div class="chisimba-notice chisimba-notice--success" role="status"><?php echo $e($systemMessage);?></div><?php endif;?><?php if($systemError):?><div class="chisimba-notice chisimba-notice--error" role="alert"><?php echo $e($systemError);?></div><?php endif;?>
<section class="system-management__grid"><article class="chisimba-card"><h2><?php echo $icons->render('power',array('decorative'=>true));?> Maintenance mode</h2><p><strong>Status: <?php echo $systemMaintenance['active']?'Offline for non-administrators':'Online';?></strong></p><p>Planned dates are advisory and never take the site offline automatically. Only the manual controls below change availability. Administrators always retain access.</p><p>The maintenance email will quote this planned window; it will not have a separate date selector.</p><form class="chisimba-form" method="post" action="<?php echo $e($url(array('action'=>'save')));?>"><?php echo $hidden;?><input type="hidden" name="kind" value="maintenance"><div class="chisimba-form-field"><label for="maintenance-message">Offline message</label><textarea id="maintenance-message" name="message" rows="4" required><?php echo $e($systemMaintenance['message']);?></textarea></div><div class="system-management__dates"><div class="chisimba-form-field"><label for="maintenance-start">Planned start</label><input id="maintenance-start" name="start" type="datetime-local" value="<?php echo $e($systemService->storageToLocal($systemMaintenance['start']));?>"></div><div class="chisimba-form-field"><label for="maintenance-end">Planned end</label><input id="maintenance-end" name="end" type="datetime-local" value="<?php echo $e($systemService->storageToLocal($systemMaintenance['end']));?>"></div></div><div class="chisimba-form-actions"><button class="button" type="submit"><?php echo $icons->render('save',array('decorative'=>true));?> Save plan</button></div></form><form class="chisimba-form" method="post" action="<?php echo $e($url(array('action'=>'setmaintenance')));?>"><?php echo $hidden;?><div class="chisimba-form-actions"><button class="button chisimba-button-danger" type="submit" name="state" value="offline" <?php echo $systemMaintenance['active']?'disabled aria-disabled="true"':'';?>><?php echo $icons->render('power-off',array('decorative'=>true));?> Take site offline</button><button class="button" type="submit" name="state" value="online" <?php echo $systemMaintenance['active']?'':'disabled aria-disabled="true"';?>><?php echo $icons->render('power',array('decorative'=>true));?> Bring site online</button></div></form></article>
<article class="chisimba-card"><h2><?php echo $icons->render('megaphone',array('decorative'=>true));?> Schedule an in-site notice</h2><p>These dates control an independent notice shown inside the site. They do not alter the maintenance window or send email.</p><form class="chisimba-form" method="post" action="<?php echo $e($url(array('action'=>'save')));?>"><?php echo $hidden;?><input type="hidden" name="kind" value="notice"><div class="chisimba-form-field"><label for="notice-title">Title</label><input id="notice-title" name="title" maxlength="255" required></div><div class="chisimba-form-field"><label for="notice-message">Message</label><textarea id="notice-message" name="notice_message" rows="4" required></textarea></div><div class="chisimba-form-field"><label for="notice-audience">Audience</label><select id="notice-audience" name="audience"><option value="everyone">Everyone</option><option value="admins">Administrators</option><option value="lecturers">Lecturers</option><option value="students">Students</option></select></div><div class="system-management__dates"><div class="chisimba-form-field"><label for="notice-start">Starts</label><input id="notice-start" name="notice_start" type="datetime-local"></div><div class="chisimba-form-field"><label for="notice-end">Ends</label><input id="notice-end" name="notice_end" type="datetime-local"></div></div><div class="chisimba-form-actions"><button class="button" type="submit"><?php echo $icons->render('calendar-plus',array('decorative'=>true));?> Schedule notice</button></div></form></article></section>
<section class="chisimba-card"><h2>Planned notices</h2><?php if(!$systemNotices):?><p>No notices have been scheduled.</p><?php else:?><div class="system-management__notices"><?php foreach($systemNotices as $notice):?><article><div><span class="chisimba-pill"><?php echo $e(ucfirst($notice['audience']));?></span><h3><?php echo $e($notice['title']);?></h3><p><?php echo nl2br($e($notice['message']));?></p><small><?php echo $e(($notice['starts_at']?$systemClock->formatDateTime($notice['starts_at']):'Immediately').' — '.($notice['ends_at']?$systemClock->formatDateTime($notice['ends_at']):'No end date'));?></small></div><form method="post" action="<?php echo $e($url(array('action'=>'deletenotice')));?>"><?php echo $hidden;?><input type="hidden" name="id" value="<?php echo $e($notice['id']);?>"><button class="button chisimba-button-danger" type="submit"><?php echo $icons->render('trash-2',array('decorative'=>true));?> Remove</button></form></article><?php endforeach;?></div><?php endif;?></section></main>
